window.CARD_CODE="import React from 'react';\r\n\r\nimport getProxyFormState from './logic/getProxyFormState';\r\nimport type {\r\n  FieldValues,\r\n  FormState,\r\n  UseFormStateProps,\r\n  UseFormStateReturn,\r\n} from './types';\r\nimport { useFormControlContext } from './useFormControlContext';\r\nimport { useIsomorphicLayoutEffect } from './useIsomorphicLayoutEffect';\r\nimport { cloneFormState, useResyncOnReconnect } from './useResyncOnReconnect';\r\n\r\n/**\r\n * Subscribes to form state with re-renders isolated to this hook.\r\n * Optionally scope to specific field names to minimize re-render surface.\r\n *\r\n * @see [API](https://react-hook-form.com/docs/useformstate)\r\n *\r\n * @example\r\n * ```tsx\r\n * const { errors, isDirty } = useFormState({ control, name: \"email\" });\r\n * ```\r\n */\r\nexport function useFormState<\r\n  TFieldValues extends FieldValues = FieldValues,\r\n  TTransformedValues = TFieldValues,\r\n>(\r\n  props?: UseFormStateProps<TFieldValues, TTransformedValues>,\r\n): UseFormStateReturn<TFieldValues> {\r\n  const formControl = useFormControlContext<\r\n    TFieldValues,\r\n    unknown,\r\n    TTransformedValues\r\n  >();\r\n  const { control = formControl, disabled, name, exact } = props || {};\r\n\r\n  const getCurrentFormState = () => ({\r\n    ...control._formState,\r\n    defaultValues:\r\n      control._defaultValues as FormState<TFieldValues>['defaultValues'],\r\n  });\r\n\r\n  const [formState, updateFormState] =\r\n    React.useState<FormState<TFieldValues>>(getCurrentFormState);\r\n  const _localProxyFormState = React.useRef({\r\n    isDirty: false,\r\n    isLoading: false,\r\n    dirtyFields: false,\r\n    touchedFields: false,\r\n    validatingFields: false,\r\n    isValidating: false,\r\n    isValid: false,\r\n    errors: false,\r\n  });\r\n\r\n  const { resyncIfNeeded, snapshot } = useResyncOnReconnect<\r\n    FormState<TFieldValues>\r\n  >(getCurrentFormState, cloneFormState);\r\n\r\n  useIsomorphicLayoutEffect(() => {\r\n    resyncIfNeeded(!disabled, getCurrentFormState, updateFormState);\r\n\r\n    const unsubscribe = control._subscribe({\r\n      name,\r\n      formState: _localProxyFormState.current,\r\n      exact,\r\n      callback: (formState) => {\r\n        !disabled &&\r\n          updateFormState({\r\n            ...control._formState,\r\n            ...formState,\r\n            defaultValues:\r\n              control._defaultValues as FormState<TFieldValues>['defaultValues'],\r\n          });\r\n      },\r\n    });\r\n\r\n    return () => {\r\n      unsubscribe();\r\n      snapshot(!disabled, getCurrentFormState);\r\n    };\r\n  }, [control, name, disabled, exact, resyncIfNeeded, snapshot]);\r\n\r\n  React.useEffect(() => {\r\n    _localProxyFormState.current.isValid && control._setValid(true);\r\n  }, [control]);\r\n\r\n  return React.useMemo(\r\n    () =>\r\n      getProxyFormState(\r\n        formState,\r\n        control,\r\n        _localProxyFormState.current,\r\n        false,\r\n      ),\r\n    [formState, control],\r\n  );\r\n}\r\n";
